- SOURCE_CLAIM_JSON: {"title":"Egypt central bank holds rates steady after change of governor","publisher":"Reuters via Investing.com","publication_date":"2022-08-18","url":"https://www.investing.com/news/economy/egypt-central-bank-keeps-interest-rates-unchanged-2875878","claim":"President Abdel Fattah al-Sisi appointed Hassan Abdalla as caretaker central bank governor after Tarek Amer resigned amid a currency crisis, and the new governor was described as a veteran financier with banking experience.","locator":"lines 424-427","source_type":"media","source_confidence":"medium_high","source_confidence_reason":"Reuters wire reporting with direct attribution and relevant biographical context.","final_evidence_use":"final_evidence","period_fit":"Exact 2022 fit.","ruler_attribution":"A direct personnel decision by Sisi over a key macroeconomic institution.","contrary_evidence":["The appointment came during crisis management, so it is not by itself proof of policy competence.","The source mixes competence with state-linked career background, so it is not a clean technocratic merit signal."],"lenses":["5B.2","5B.3","5B.7"]}
- SOURCE_CLAIM_JSON: {"title":"Egypt's pound sinks further against dollar after flexibility pledge","publisher":"Reuters via L'Orient Today","publication_date":"2022-10-30","url":"https://today.lorientlejour.com/article/1316318/egypts-pound-sinks-further-against-dollar-after-flexibility-pledge.html","claim":"After authorities pledged a durably flexible exchange rate under an IMF support deal, Egypt's pound fell further and had weakened about 34 percent against the dollar during 2022.","locator":"lede and first two paragraphs","source_type":"media","source_confidence":"medium_high","source_confidence_reason":"Reuters wire reporting with clear macro-policy and market reaction, syndicated by a reputable outlet.","final_evidence_use":"final_evidence","period_fit":"Exact 2022 fit.","ruler_attribution":"Relevant to the Sisi administration's macro stance and external-balance management.","contrary_evidence":["The market reaction shows fragility, not successful stabilization.","The article reflects an IMF-linked policy pledge rather than completed reform."],"lenses":["5B.3","5B.9","5B.10"]}
- SOURCE_CLAIM_JSON: {"title":"بيان صحفي 27 أكتوبر 2022","publisher":"Central Bank of Egypt","publication_date":"2022-10-27","url":"https://www.cbe.org.eg/ar/news-publications/news/2022/10/press-release---october-27%2C-2022","claim":"The Monetary Policy Committee raised policy rates by 200 basis points and said the move was meant to contain inflationary pressures and support the inflation-targeting path.","locator":"press-release text in the Arabic announcement","source_type":"official","source_confidence":"high","source_confidence_reason":"Primary central-bank policy statement from the exact date of the move.","final_evidence_use":"final_evidence","period_fit":"Exact 2022 fit.","ruler_attribution":"Attributable to the CBE under Sisi's presidency; it shows active macro policy management, not independent central-bank behavior detached from the executive.","contrary_evidence":["Rate hikes help stability but also tighten credit and can slow activity.","The page is a policy announcement, not an evaluation of success."],"lenses":["5B.3","5B.7","5B.9"]}
